+// enforceClientCertSANSuffixPolicy checks the client certificate's SANs against the configured allow-list.
+// If the allow-list is empty, no restriction is enforced.
+func (s *ProxyServer) enforceClientCertSANSuffixPolicy(r *http.Request) error {
+	if len(s.cfg.ClientCertSANSuffixAllowList) == 0 {
+		return nil
+	}
+	connState := getTLSConnectionState(r)
+	if connState == nil || len(connState.PeerCertificates) == 0 {
+		return errors.New("no client certificate presented")
+	}
+	cert := connState.PeerCertificates[0]
+	allowed := false
+	// Check DNS SANs
+	for _, san := range cert.DNSNames {
+		for _, suffix := range s.cfg.ClientCertSANSuffixAllowList {
+			if strings.HasSuffix(san, suffix) {
+				allowed = true
+				break
+			}
+		}
+		if allowed {
+			break
+		}
+	}
+	// Optionally, check URI SANs
+	if !allowed {
+		for _, uri := range cert.URIs {
+			if uri == nil {
+				continue
+			}
+			for _, suffix := range s.cfg.ClientCertSANSuffixAllowList {
+				if strings.HasSuffix(uri.String(), suffix) {
+					allowed = true
+					break
+				}
+			}
+			if allowed {
+				break
+			}
+		}
+	}
+	if !allowed {
+		return fmt.Errorf("client certificate SAN does not match allowed suffixes: %v", s.cfg.ClientCertSANSuffixAllowList)
+	}
+	return nil
+}
