+// logClientCertAudit logs the client certificate subject and serial number on session.start for auditability.
+func (s *ProxyServer) logClientCertAudit(r *http.Request, claims *jwtutil.Claims, dest string) {
+	connState := getTLSConnectionState(r)
+	if connState == nil || len(connState.PeerCertificates) == 0 {
+		return
+	}
+	cert := connState.PeerCertificates[0]
+	s.log.Info("proxy.audit", zap.String("event", "session.client_cert"),
+		zap.String("remote", r.RemoteAddr),
+		zap.String("dest", dest),
+		zap.String("cert_subject", cert.Subject.String()),
+		zap.String("cert_serial", cert.SerialNumber.String()),
+		zap.String("wid", claims.Wid),
+		zap.String("sub", claims.Sub),
+		zap.String("jti", claims.ID),
+	)
+}
+
+// getTLSConnectionState extracts the TLS connection state from the request's context.
+func getTLSConnectionState(r *http.Request) *tls.ConnectionState {
+	if r == nil || r.TLS == nil {
+		return nil
+	}
+	return r.TLS
+}
